#!/usr/bin/env python3
"""
Fix §18 references by adding missing concept mentions in body or removing irrelevant ones.
Processes all 7 files.
"""
import re, os

VAULT = "/sdcard/Nexus_Brain/nexus_vault"

def add_wikilinks_to_body(body, section_marker, additions):
    """Add sentences before a section marker in the body."""
    idx = body.find(section_marker)
    if idx == -1:
        print(f"  WARNING: Section '{section_marker}' not found!")
        return body
    # Find end of the previous paragraph
    # Insert before the section marker
    insert_text = "\n\n" + "\n\n".join(additions) + "\n\n"
    body = body[:idx] + insert_text + body[idx:]
    return body

def find_section_end(body, section_header):
    """Find the end of a section (next ## or end of file)."""
    idx = body.find(section_header)
    if idx == -1:
        return -1
    # Find the next ## that's not a subsection of this one
    rest = body[idx + len(section_header):]
    next_idx = -1
    # Find next ## not containing a dot (meaning a new section, not subsection)
    for m in re.finditer(r'^## ', rest, re.MULTILINE):
        next_idx = idx + len(section_header) + m.start()
        break
    if next_idx == -1:
        return len(body)
    return next_idx

def edit_file(filepath, body_edits, section18_removals=None):
    """Apply edits to a file."""
    with open(filepath, 'r') as f:
        content = f.read()

    body_end = content.find("## §18")
    if body_end == -1:
        body_end = content.find("## § 18")

    if body_end == -1:
        print(f"  ERROR: No §18 in {filepath}")
        return

    body = content[:body_end]
    sec18 = content[body_end:]

    # Apply body edits
    for edit in body_edits:
        if edit["type"] == "after":
            # Find section end and add before the next section
            sec_end = find_section_end(body, edit["section"])
            if sec_end == -1:
                print(f"  WARNING: Section '{edit['section']}' not found")
                continue
            # Find the end of the last line in this section
            text_before = body[sec_end:].lstrip()
            actual_end = sec_end + (len(body[sec_end:]) - len(text_before))
            insertion = "\n" + edit["text"] + "\n"
            body = body[:actual_end] + insertion + body[actual_end:]
        elif edit["type"] == "before_section":
            idx = body.find(edit["section"])
            if idx == -1:
                print(f"  WARNING: Section '{edit['section']}' not found")
                continue
            insertion = "\n\n" + edit["text"] + "\n\n"
            body = body[:idx] + insertion + body[idx:]

    # Apply §18 removals
    if section18_removals:
        for removal in section18_removals:
            # Remove the line(s) containing this concept
            pattern = r'\[\[{}\]\].*?(?:\n|$)'.format(re.escape(removal))
            sec18 = re.sub(pattern, '', sec18)
            # Also remove lines that are just the bare wikilink
            pattern2 = r'- \[\[{}\]\]\s*\n'.format(re.escape(removal))
            sec18 = re.sub(pattern2, '', sec18)
            # Remove blank lines that result
            sec18 = re.sub(r'\n{3,}', '\n\n', sec18)

    new_content = body + sec18

    # Backup original
    # os.system(f"cp '{filepath}' '{filepath}.bak'")

    with open(filepath, 'w') as f:
        f.write(new_content)

    print(f"  ✓ Updated {filepath}")

